import * as fs from 'node:fs';
import * as path from 'node:path';
import type { Plan, PlanGroup, PlanItem } from '../contracts/types';
import { EditRefused } from '../core/lineEdit';
import { commitAll, gitRepo, gitSync, item } from '../testing/helpers';
import { realExec } from '../util/exec';
import { OK, editFile, tokenOnNamedLine, type Adapter, type StepOutcome } from './adapter';
import { applyPlan, applyGroup, type OrchestratorOptions } from './orchestrator';

/**
 * A fake ecosystem on REAL git: `deps.txt` holds `name version` lines, `deps.lock` is regenerated by
 * the fake "tool" from deps.txt. The tool can be told to fail for a package (and to scribble on the
 * lockfile and leave a stray file behind while failing, as NuGet does, S13).
 */
function fakeAdapter(opts: { failOn?: string[]; consistencyFailsWith?: string; missingTool?: boolean } = {}): Adapter & { calls: string[] } {
  const calls: string[] = [];
  const relockText = (root: string) =>
    fs.readFileSync(path.join(root, 'deps.txt'), 'utf8').split('\n').filter(Boolean).map((l) => `${l} sha-${l.split(' ')[1]}`).join('\n') + '\n';
  return {
    id: 'fake',
    calls,
    matches: (i) => i.datasource === 'fake',
    files: async (_ctx, i) => [i.packageFile, 'deps.lock'],
    async edit(ctx, i) {
      calls.push(`edit ${i.depName}`);
      await editFile(ctx, i.packageFile, tokenOnNamedLine(new RegExp(`^${i.depName} `), i.currentValue, i.newValue));
    },
    async pin(_ctx, items) {
      calls.push(`pin ${items.map((i) => i.depName).join(',')}`);
      return OK;
    },
    async relock(ctx, items): Promise<StepOutcome> {
      calls.push(`relock ${items.map((i) => i.depName).join(',')}`);
      const bad = items.find((i) => opts.failOn?.includes(i.depName));
      if (bad) {
        // Like a failed NuGet restore: the lockfile is rewritten anyway, and a stray file appears.
        fs.writeFileSync(path.join(ctx.root, 'deps.lock'), 'CORRUPTED\n');
        fs.writeFileSync(path.join(ctx.root, 'stray.tmp'), 'left behind');
        return { ok: false, output: `CONFLICT: ${bad.depName}@${bad.newVersion} needs peer other@^9`, kind: 'resolver' };
      }
      fs.writeFileSync(path.join(ctx.root, 'deps.lock'), relockText(ctx.root));
      return OK;
    },
    async verify() {
      calls.push('verify');
      return OK;
    },
    parseBlockers: (output) => {
      const m = output.match(/needs peer (\S+?)@(\S+)/);
      return m ? [{ depName: m[1], version: m[2], code: 'FAKE', message: output }] : [];
    },
    consistencyDir: () => '.',
    async consistency(ctx) {
      const txt = fs.readFileSync(path.join(ctx.root, 'deps.txt'), 'utf8');
      if (opts.consistencyFailsWith && txt.includes(opts.consistencyFailsWith)) return { ok: false, output: `inconsistent: ${opts.consistencyFailsWith}`, kind: 'resolver' };
      return OK;
    },
    tools: () => (opts.missingTool ? ['definitely-not-installed-tool'] : []),
  };
}

const fakeItem = (depName: string, from: string, to: string): PlanItem =>
  item({ depName, datasource: 'fake', manager: 'fake', packageFile: 'deps.txt', lockFiles: ['deps.lock'], currentValue: from, newValue: to });

function repo() {
  const deps = 'a 1.0.0\nb 1.0.0\nc 1.0.0\n';
  const lock = 'a 1.0.0 sha-1.0.0\nb 1.0.0 sha-1.0.0\nc 1.0.0 sha-1.0.0\n';
  return gitRepo({ 'deps.txt': deps, 'deps.lock': lock, 'README.md': 'x\n' });
}

const plan = (sha: string, groups: PlanGroup[]): Plan => ({ contractVersion: 1, kind: 'plan', planId: 'p', expectedSha: sha, groups });

function options(root: string, adapter: Adapter, extra: Partial<OrchestratorOptions> = {}): OrchestratorOptions {
  return { root, exec: realExec, feedSecrets: false, consistencyCheck: true, adapters: [adapter], toolAvailable: async (t) => t !== 'definitely-not-installed-tool', ...extra };
}

describe('group-by-group apply with exact reset (R2, D-S13a, D-C2)', () => {
  it('ships groups 1 and 3 when group 2 conflicts, and leaves no trace of group 2', async () => {
    const { dir, sha } = repo();
    const a = fakeAdapter({ failOn: ['b'] });
    const r = await applyPlan(
      plan(sha, [
        { group: 'g-a', items: [fakeItem('a', '1.0.0', '1.1.0')] },
        { group: 'g-b', items: [fakeItem('b', '1.0.0', '2.0.0')] },
        { group: 'g-c', items: [fakeItem('c', '1.0.0', '1.0.1')] },
      ]),
      options(dir, a),
    );
    expect(r.groups.map((g) => g.status)).toEqual(['applied', 'unresolvable', 'applied']);
    expect(r.groups[1].blockers).toEqual([expect.objectContaining({ depName: 'other', version: '^9', code: 'FAKE' })]);
    expect(r.groups[1].message).toMatch(/CONFLICT: b@2\.0\.0/);
    expect(fs.readFileSync(path.join(dir, 'deps.txt'), 'utf8')).toBe('a 1.1.0\nb 1.0.0\nc 1.0.1\n');
    expect(fs.readFileSync(path.join(dir, 'deps.lock'), 'utf8')).toBe('a 1.1.0 sha-1.1.0\nb 1.0.0 sha-1.0.0\nc 1.0.1 sha-1.0.1\n');
    expect(fs.existsSync(path.join(dir, 'stray.tmp'))).toBe(false);
    expect(r.groups[0].files).toEqual(['deps.lock', 'deps.txt']);
    expect(r.groups[1].files).toEqual([]);
    expect(r.consistency).toEqual({ status: 'passed', checks: [{ adapter: 'fake', directory: '.', ok: true, message: null }], bisected: [] });
  });

  it('runs edit -> pin -> relock -> verify in that order', async () => {
    const { dir } = repo();
    const a = fakeAdapter();
    await applyGroup(options(dir, a), { group: 'g', items: [fakeItem('a', '1.0.0', '1.1.0'), fakeItem('b', '1.0.0', '1.1.0')] });
    expect(a.calls).toEqual(['edit a', 'edit b', 'pin a,b', 'relock a,b', 'verify']);
  });

  it('pins first for a pinFirst adapter (Cargo, S13)', async () => {
    const { dir } = repo();
    const a = { ...fakeAdapter(), pinFirst: true };
    const calls: string[] = [];
    a.pin = async () => (calls.push('pin'), OK);
    a.edit = async () => void calls.push('edit');
    a.relock = async () => (calls.push('relock'), OK);
    a.verify = async () => (calls.push('verify'), OK);
    await applyGroup(options(dir, a), { group: 'g', items: [fakeItem('a', '1.0.0', '1.1.0')] });
    expect(calls).toEqual(['pin', 'edit', 'relock', 'verify']);
  });

  it('a refused edit fails the group (not unresolvable) and resets it', async () => {
    const { dir } = repo();
    const r = await applyGroup(options(dir, fakeAdapter()), { group: 'g', items: [fakeItem('a', '1.0.0', '1.1.0'), fakeItem('b', '9.9.9', '10.0.0')] });
    expect(r.status).toBe('failed');
    expect(r.message).toMatch(/^edit refused:/);
    expect(fs.readFileSync(path.join(dir, 'deps.txt'), 'utf8')).toBe('a 1.0.0\nb 1.0.0\nc 1.0.0\n');
  });

  it('a missing tool fails the group before anything runs', async () => {
    const { dir } = repo();
    const a = fakeAdapter({ missingTool: true });
    const r = await applyGroup(options(dir, a), { group: 'g', items: [fakeItem('a', '1.0.0', '1.1.0')] });
    expect(r).toMatchObject({ status: 'failed', message: "fake: tool 'definitely-not-installed-tool' is not available on the runner" });
    expect(a.calls).toEqual([]);
  });

  it('an item no adapter handles fails its group by name', async () => {
    const { dir } = repo();
    const r = await applyGroup(options(dir, fakeAdapter()), {
      group: 'g',
      items: [item({ depName: 'rails', datasource: 'rubygems', packageFile: 'Gemfile', currentValue: '7.0.0', newValue: '7.1.0' })],
    });
    expect(r.status).toBe('failed');
    expect(r.message).toBe('no apply adapter for rails (datasource rubygems, Gemfile)');
    expect(r.items[0].adapter).toBeNull();
  });

  it('an adapter that throws something unexpected fails the group and still resets', async () => {
    const { dir } = repo();
    const a = fakeAdapter();
    a.verify = async () => {
      throw new Error('kaboom');
    };
    const r = await applyGroup(options(dir, a), { group: 'g', items: [fakeItem('a', '1.0.0', '1.1.0')] });
    expect(r.status).toBe('failed');
    expect(r.message).toMatch(/unexpected error: Error: kaboom/);
    expect(gitSync(dir, 'status', '--porcelain')).toBe('');
  });

  it('an EditRefused thrown from pin is a failed group too', async () => {
    const { dir } = repo();
    const a = fakeAdapter();
    a.pin = async () => {
      throw new EditRefused('deps.txt', 'nope', 0);
    };
    expect((await applyGroup(options(dir, a), { group: 'g', items: [fakeItem('a', '1.0.0', '1.1.0')] })).status).toBe('failed');
  });
});

describe('whole-tree consistency check with bisect (D-C3)', () => {
  it('drops exactly the group after which the tree stops being consistent, and keeps the rest', async () => {
    const { dir, sha } = repo();
    const a = fakeAdapter({ consistencyFailsWith: 'b 2.0.0' });
    const r = await applyPlan(
      plan(sha, [
        { group: 'g-a', items: [fakeItem('a', '1.0.0', '1.1.0')] },
        { group: 'g-b', items: [fakeItem('b', '1.0.0', '2.0.0')] },
        { group: 'g-c', items: [fakeItem('c', '1.0.0', '1.0.1')] },
      ]),
      options(dir, a),
    );
    expect(r.groups.map((g) => `${g.group}:${g.status}`)).toEqual(['g-a:applied', 'g-b:failed', 'g-c:applied']);
    expect(r.groups[1].message).toMatch(/consistency check \(D-C3 bisect\).*inconsistent: b 2\.0\.0/s);
    expect(r.consistency.bisected).toEqual(['g-b']);
    expect(r.consistency.status).toBe('passed');
    expect(fs.readFileSync(path.join(dir, 'deps.txt'), 'utf8')).toBe('a 1.1.0\nb 1.0.0\nc 1.0.1\n');
  });

  it('is skipped when the plan turns it off', async () => {
    const { dir, sha } = repo();
    const p = { ...plan(sha, [{ group: 'g-b', items: [fakeItem('b', '1.0.0', '2.0.0')] }]), options: { consistencyCheck: false } };
    const r = await applyPlan(p, options(dir, fakeAdapter({ consistencyFailsWith: 'b 2.0.0' })));
    expect(r.consistency).toEqual({ status: 'skipped', checks: [], bisected: [] });
    expect(r.groups[0].status).toBe('applied');
  });
});

describe('platform groups', () => {
  it('applies the platform edit and the locked packages atomically, and resets both on failure', async () => {
    const { dir } = gitRepo({
      'Directory.Build.props': '<Project>\n  <PropertyGroup>\n    <TargetFramework>net10.0</TargetFramework>\n  </PropertyGroup>\n</Project>\n',
      'deps.txt': 'a 10.0.0\n',
      'deps.lock': 'a 10.0.0 sha-10.0.0\n',
    });
    const ok = await applyGroup(options(dir, fakeAdapter()), {
      group: 'platform:dotnet 11.0',
      items: [fakeItem('a', '10.0.0', '11.0.0')],
      platform: { sdk: 'dotnet', fromChannel: '10.0', toChannel: '11.0' },
    });
    expect(ok.status).toBe('applied');
    expect(ok.platform?.edited).toEqual(['Directory.Build.props']);
    expect(fs.readFileSync(path.join(dir, 'Directory.Build.props'), 'utf8')).toContain('<TargetFramework>net11.0</TargetFramework>');
    commitAll(dir, 'applied');
    const failing = await applyGroup(options(dir, fakeAdapter({ failOn: ['a'] })), {
      group: 'platform:dotnet 12.0',
      items: [fakeItem('a', '11.0.0', '12.0.0')],
      platform: { sdk: 'dotnet', fromChannel: '11.0', toChannel: '12.0' },
    });
    expect(failing.status).toBe('unresolvable');
    expect(fs.readFileSync(path.join(dir, 'Directory.Build.props'), 'utf8')).toContain('<TargetFramework>net11.0</TargetFramework>');
  });

  it('fails a platform group that finds nothing on its channel', async () => {
    const { dir } = gitRepo({ 'global.json': '{ "sdk": { "version": "9.0.100" } }\n' });
    const r = await applyGroup(options(dir, fakeAdapter()), { group: 'p', items: [], platform: { sdk: 'dotnet', fromChannel: '10.0', toChannel: '11.0' } });
    expect(r).toMatchObject({ status: 'failed', message: 'no editable dotnet location on channel 10.0' });
  });
});
